69:     @EventListener(ApplicationReadyEvent.class)
70:     public void onApplicationReady(ApplicationReadyEvent event) {
71:         // Maintenance CLIs also publish ApplicationReadyEvent with the local profile.
72:         // Only the running loopback web application owns the daily scheduler.
73:         if (!(event.getApplicationContext() instanceof org.springframework.web.context.WebApplicationContext web)
74:                 || web.getServletContext() == null
75:                 || !"127.0.0.1".equals(environment.getProperty("server.address"))) {
76:             runtimeReason="J3_WEB_APPLICATION_REQUIRED";return;
