109:     private void tickSafely() {
110:         if(stopping || !ready) return;
111:         Instant now=Instant.now();long nanos=System.nanoTime();
112:         boolean continuous=previousTick!=null && nanos-previousNanos<TimeUnit.SECONDS.toNanos(3)
113:                 && Math.abs(Duration.between(previousTick,now).toMillis()
114:                     -TimeUnit.NANOSECONDS.toMillis(nanos-previousNanos))<2000;
115:         try {
116:             String unavailable=providerUnavailableReason();
117:             orders.tick(owner,previousTick==null?now:previousTick,now,continuous,unavailable);
118:             if(pendingCleanup==null && reconciliation==null) runtimeReason=null;
119:             wakeConsumer();
120:         } catch(RuntimeException unavailable) {runtimeReason="J3_PERSISTENCE_UNAVAILABLE";}
121:         previousTick=now;previousNanos=nanos;
122:     }
