1: package com.bettingproject.sofascorelocal.application.network.playwright;
2: 
3: import com.bettingproject.sofascorelocal.domain.provider.SofascoreEndpointType;
4: 
5: import java.util.Set;
6: import java.util.UUID;
7: 
8: public interface PlaywrightProviderCampaignFactory {
9: 
10:     PlaywrightProviderCampaign open(
11:             UUID campaignId,
12:             Set<SofascoreEndpointType> allowedEndpoints);
13: 
14:     /** Explicit live-v4 policy; historical factories remain unchanged. */
15:     default PlaywrightProviderCampaign openLiveGrouped(
16:             UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
17:         throw new UnsupportedOperationException("grouped live dispatch is not implemented by this transport");
18:     }
19: 
20:     /** Explicit live-v5 server authority; never falls back to a historical factory. */
21:     default PlaywrightProviderCampaign openLiveGroupedV5(
22:             UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
23:         throw new UnsupportedOperationException("grouped live-v5 dispatch is not implemented by this transport");
24:     }
25: 
26:     /** Explicit live-v6 authority, allowing unavailable in-play families to be deferred. */
27:     default PlaywrightProviderCampaign openLiveGroupedV6(
28:             UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
29:         throw new UnsupportedOperationException("grouped live-v6 dispatch is not implemented by this transport");
30:     }
31: 
32:     /** Explicit V7 kickoff-window authority; no fallback can silently grant prematch groups. */
33:     default PlaywrightProviderCampaign openLiveGroupedV7(UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
34:         throw new UnsupportedOperationException("grouped live-v7 dispatch is not implemented by this transport");
35:     }
36: 
37:     /** Explicit V8 ten-match authority; it cannot fall back to an earlier live policy. */
38:     default PlaywrightProviderCampaign openLiveGroupedV8(UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
39:         throw new UnsupportedOperationException("grouped live-v8 dispatch is not implemented by this transport");
40:     }
41: 
42:     /**
43:      * Explicit V9 J4-controlled authority. Its scheduling gates reduce work, while its
44:      * transport pressure remains bounded by the previously qualified V8 local profile.
45:      */
46:     default PlaywrightProviderCampaign openLiveGroupedV9(UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
47:         throw new UnsupportedOperationException("grouped live-v9 dispatch is not implemented by this transport");
48:     }
49: 
50:     /** Explicit V10 eight-match authority; it never falls back to a historical profile. */
51:     default PlaywrightProviderCampaign openLiveGroupedV10(UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
52:         throw new UnsupportedOperationException("grouped live-v10 dispatch is not implemented by this transport");
53:     }
54: 
55:     /** V11 preserves V10 pressure and adds the separately qualified J3 pause capability. */
56:     default PlaywrightProviderCampaign openLiveGroupedV11(UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
57:         throw new UnsupportedOperationException("grouped live-v11 dispatch is not implemented by this transport");
58:     }
59: 
60:     /** One explicitly launched, single-event J5 manual group in statistics/incidents/lineups order. */
61:     default PlaywrightProviderCampaign openManualJ5Grouped(
62:             UUID campaignId, Set<SofascoreEndpointType> allowedEndpoints) {
63:         throw new UnsupportedOperationException("grouped manual J5 dispatch is not implemented by this transport");
64:     }
65: }
